ALTER TABLE public.parties ADD COLUMN credit_limit numeric(14,2) CHECK(credit_limit>=0 AND credit_limit<=999999999);
ALTER TABLE public.business_settings ADD COLUMN payment_qr_path text, ADD COLUMN payment_provider text NOT NULL DEFAULT '', ADD COLUMN payment_payee text NOT NULL DEFAULT '', ADD COLUMN payment_instructions text NOT NULL DEFAULT '';
ALTER TABLE public.business_settings ADD CONSTRAINT payment_qr_scope CHECK(payment_qr_path IS NULL OR (payment_qr_path LIKE business_id::text||'/%' AND payment_qr_path !~ '\.\.'));
CREATE TABLE public.quotations(id uuid PRIMARY KEY,business_id uuid NOT NULL REFERENCES public.businesses(id) ON DELETE RESTRICT,branch_id uuid NOT NULL,party_id uuid NOT NULL,reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),quotation_date date NOT NULL,expires_on date,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','accepted','declined','converted')),customer jsonb NOT NULL,lines jsonb NOT NULL,total numeric(14,2) NOT NULL CHECK(total>=0),revision integer NOT NULL DEFAULT 1,sale_id uuid REFERENCES public.commerce_documents(id) ON DELETE RESTRICT,request jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_id,id),UNIQUE(business_id,reference),FOREIGN KEY(business_id,branch_id) REFERENCES public.branches(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(business_id,party_id) REFERENCES public.parties(business_id,id) ON DELETE RESTRICT,CHECK(expires_on IS NULL OR expires_on>=quotation_date));
REVOKE ALL ON public.quotations FROM PUBLIC,anon,authenticated;GRANT SELECT ON public.quotations TO authenticated;GRANT ALL ON public.quotations TO service_role;
ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY;CREATE POLICY quotation_read ON public.quotations FOR SELECT TO authenticated USING(public.can_access_branch(business_id,branch_id));CREATE INDEX quotation_branch_date ON public.quotations(business_id,branch_id,quotation_date DESC);
ALTER TABLE public.commerce_documents ADD COLUMN quotation_id uuid;ALTER TABLE public.commerce_documents ADD CONSTRAINT commerce_quotation_fk FOREIGN KEY(business_id,quotation_id) REFERENCES public.quotations(business_id,id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX quotation_confirmed_sale ON public.commerce_documents(quotation_id) WHERE quotation_id IS NOT NULL AND status='confirmed' AND kind='sale';
CREATE POLICY payment_qr_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='payment-qr' AND public.is_business_member(public.bill_object_business(name)));
CREATE POLICY payment_qr_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='payment-qr' AND public.has_business_role(public.bill_object_business(name),'admin') AND lower(storage.extension(name)) IN ('png','jpg','jpeg'));
CREATE POLICY payment_qr_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='payment-qr' AND public.has_business_role(public.bill_object_business(name),'admin'));
CREATE TRIGGER quotation_audit AFTER INSERT OR UPDATE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.audit_row();